import { env } from 'cloudflare:workers'

// Session IDs are generated by the booth: 10 base62 characters.
const ID_PATTERN = /^[A-Za-z0-9]{10}$/

export function isValidId(id: string) {
  return ID_PATTERN.test(id)
}

// Only the booth orchestrator knows BOOTH_SECRET; it never reaches a browser.
export function isBooth(request: Request) {
  const given = request.headers.get('x-booth-secret')
  return Boolean(env.BOOTH_SECRET) && given === env.BOOTH_SECRET
}

export function photoKey(id: string) {
  return `photos/${id}.jpg`
}

export type SessionRow = {
  id: string
  condition: string | null
  captured_at: string | null
  uploaded_at: string | null
  photo_key: string | null
  submitted_at: string | null
  survey_version: number | null
  answers: string | null
}

export async function getSession(id: string) {
  return env.DB.prepare('SELECT * FROM sessions WHERE id = ?')
    .bind(id)
    .first<SessionRow>()
}

export function jsonError(status: number, error: string) {
  return Response.json({ error }, { status })
}
